mapper.select:
SELECT rule.*, version.version, version.url, version.id as versionId FROM bm_operate_rule AS rule JOIN lm_resource_permission bm ON rule.id = bm.resource_id join bm_operate_rule_version as version on rule.id = version.operate_id WHERE rule.is_deleted = 0 and version.is_deleted = 0 and version.state =#{state} and bm.dept_id in
#{item}
and rule.id in
#{ruleId}
group by rule.id
